<script setup lang="ts">
import {placementAnatomies} from '../../../packages/reference/placement-context';
import {localize} from './localization';

import {placementReason} from './modules/mappingFeedback';
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {bodyParts,partName,sideName,type BodyPart,type BodySide} from '../../../packages/reference/body-parts';
import LegacyProjection from './LegacyProjection.vue';
import SourceRegionEditor from './SourceRegionEditor.vue';
import type {SourceEdit} from '../../../packages/reference/source-edit';
import {useSession} from './store';
import {piecePath,pointBounds} from '../../../packages/pattern/edit';
import type {Project,Piece} from '../../../packages/schema/index';
type Region=NonNullable<Project['patternLibrary']>[number];
const props=defineProps<{language:'zh'|'en';targetId?:string;drawer?:boolean}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const emit=defineEmits<{select:[id:string]}>();
const editorDirty=ref(false),sourceReset=ref(0),sourceSaveError=ref(''),pendingSelection=ref<string|null>(null);
function selectRegion(id:string){if(editorDirty.value&&selected.value!==id){pendingSelection.value=id;emit('select',selected.value);return;}selected.value=id;emit('select',id);}
function discardSwitch(){const id=pendingSelection.value;if(id===null)return;editorDirty.value=false;sourceReset.value++;pendingSelection.value=null;selectRegion(id);}
async function saveSource(edit:SourceEdit){const p=store.data.project,r=region.value;if(!p||!r||store.busy)return;sourceSaveError.value='';if(await store.run(()=>window.fpcad.editLibraryRegion(p.id,p.revision,r.piece.id,edit))){sourceReset.value++;editorDirty.value=false;pendingSelection.value=null;emit('select',r.piece.id);attachNotice.value=zh.value?'源花纹已更新，原图轮廓已同步。':localize('Source saved; the original outline is updated.');}else sourceSaveError.value=store.error;}
const attachNotice=ref(''),checked=ref<string[]>([]),pendingDelete=ref<string[]>([]);
function toggleChecked(id:string){checked.value=checked.value.includes(id)?checked.value.filter(x=>x!==id):[...checked.value,id];}
async function deleteIds(ids:string[]){const p=store.data.project;if(!p||!ids.length||store.busy||editorDirty.value)return;if(await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'library.regions.delete',pieceIds:[...ids]}))){checked.value=checked.value.filter(id=>!ids.includes(id));pendingDelete.value=[];}}
function libraryKey(e:KeyboardEvent){if((e.target as HTMLElement).closest('input,select,textarea,[contenteditable],.source-region-editor'))return;if(e.key==='Delete'&&!editorDirty.value){e.preventDefault();e.stopPropagation();const ids=checked.value.length?checked.value:selected.value?[selected.value]:[];if(ids.length===1)void deleteIds(ids);else pendingDelete.value=[...ids];}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();e.stopPropagation();checked.value=regions.value.map(r=>r.piece.id);}}

const libraryContent=ref<HTMLElement>(),detailShare=ref(.68);
const detailDrag=ref(false);
function resizeDetail(e:PointerEvent){if(!detailDrag.value||!libraryContent.value)return;const b=libraryContent.value.getBoundingClientRect();detailShare.value=Math.max(.2,Math.min(.9,1-(e.clientY-b.top)/b.height));}
function endDetail(){detailDrag.value=false;try{localStorage.setItem('fpcad.library.detail',String(detailShare.value));localStorage.setItem('fpcad.library.width',String(width.value));}catch{}}
onMounted(()=>{try{const d=Number(localStorage.getItem('fpcad.library.detail')),w=Number(localStorage.getItem('fpcad.library.width'));if(d>=.2&&d<=.9)detailShare.value=d;if(w>=240)width.value=Math.min(w,window.innerWidth*.6);}catch{}});
const selected=ref(''),search=ref(''),zoom=ref(1),offsetX=ref(0),offsetY=ref(0),width=ref(300),opened=ref(true),replaceManual=ref(false);
const narrow=window.matchMedia('(max-width:1100px)'),fitDrawer=()=>{if(props.drawer&&narrow.matches)opened.value=false;};
onMounted(()=>{fitDrawer();narrow.addEventListener('change',fitDrawer);});onBeforeUnmount(()=>narrow.removeEventListener('change',fitDrawer));
const regions=computed(()=>store.data.project?.patternLibrary??[]),region=computed(()=>regions.value.find(r=>r.piece.id===selected.value));
const filtered=computed(()=>regions.value.filter(r=>(r.piece.name+r.category+partName(r.anatomy?.part??'unknown',zh.value)+r.view+r.piece.color).toLowerCase().includes(search.value.toLowerCase())));
const groups=computed(()=>[...new Set(filtered.value.map(r=>partName(r.anatomy?.part??'unknown',zh.value)+' / '+r.view))].map(key=>({key,items:filtered.value.filter(r=>partName(r.anatomy?.part??'unknown',zh.value)+' / '+r.view===key)})));
watch(()=>props.targetId,id=>{if(!id)selectRegion('');else if(regions.value.some(r=>r.piece.id===id))selectRegion(id);},{immediate:true});
watch(selected,()=>{attachNotice.value='';editorDirty.value=false;replaceManual.value=false;});
watch(regions,list=>{checked.value=checked.value.filter(id=>list.some(r=>r.piece.id===id));if(!list.some(r=>r.piece.id===selected.value))selected.value='';});
function box(piece:Piece){const b=pointBounds(piece.nodes);return `${b.minX-5} ${-b.maxY-5} ${b.maxX-b.minX+10} ${b.maxY-b.minY+10}`;}
async function put(next:Region){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'library.region.put',region:JSON.parse(JSON.stringify(next))}));}
async function metadata(field:'name'|'color'|'category',value:string){const r=region.value;if(!r)return;await put(field==='category'?{...r,category:value}:{...r,piece:{...r.piece,[field]:value}});}
async function classify(part:BodyPart,side:BodySide){const r=region.value;if(r)await put({...r,category:partName(part),anatomy:{part,side,confidence:1,method:'manual'}});}
async function autoAttach(){const p=store.data.project,r=region.value;if(p&&r){attachNotice.value='';await store.run(async()=>{const result=await window.fpcad.autoPlaceMarkings(p.id,p.revision,[r.piece.id]);if(result.ok){const report=result.autoPlacementReport;attachNotice.value=report?.placed?(zh.value?'已贴附，请旋转模型检查并确认位置。':localize('Attached. Rotate, inspect and approve the position.')):(report?.skipped.map(item=>placementReason(item.reason,zh.value)).join(' · ')??'');}return result;});}}
async function remove(){const p=store.data.project,r=region.value;if(p&&r)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'library.region.delete',pieceId:r.piece.id}));}
async function attach(){const p=store.data.project,r=region.value;if(p&&r)await store.run(()=>window.fpcad.projectMarking(p.id,p.revision,r.piece.id,r.view,offsetX.value,offsetY.value,replaceManual.value));}
let draggedUntil=0;
function cardClick(event:MouseEvent,id:string){if(performance.now()<draggedUntil)return;selectRegion(id);if(event.ctrlKey||event.metaKey)toggleChecked(id);}
function endSourceDrag(){draggedUntil=performance.now()+200;}
function dragSource(event:DragEvent,id:string){
 if(store.busy||editorDirty.value||!props.drawer||!event.dataTransfer){event.preventDefault();return;}
 // Dragging must not open the source editor or resize the model viewport.
 draggedUntil=performance.now()+200;const transfer=event.dataTransfer;transfer.setData('application/x-fpcad-region',id);transfer.effectAllowed='copy';
 const svg=(event.currentTarget as HTMLElement).querySelector('svg'),piece=regions.value.find(r=>r.piece.id===id)?.piece,matrix=svg?.getScreenCTM();
 if(!svg||!piece||!matrix)return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse()),bounds=pointBounds(piece.nodes);
 if(point.x>=bounds.minX&&point.x<=bounds.maxX&&-point.y>=bounds.minY&&-point.y<=bounds.maxY)transfer.setData('application/x-fpcad-anchor',JSON.stringify({xMm:point.x,yMm:-point.y}));
 const rect=svg.getBoundingClientRect(),ghost=svg.cloneNode(true) as SVGSVGElement;ghost.style.cssText=`position:fixed;left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px;pointer-events:none;z-index:-1;background:transparent;opacity:.85`;document.body.appendChild(ghost);transfer.setDragImage(ghost,Math.max(0,Math.min(rect.width,event.clientX-rect.left)),Math.max(0,Math.min(rect.height,event.clientY-rect.top)));requestAnimationFrame(()=>ghost.remove());
}
let resize:{x:number;width:number}|undefined;
function start(event:PointerEvent){resize={x:event.clientX,width:width.value};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);}
function drag(event:PointerEvent){if(resize)width.value=Math.max(240,Math.min(window.innerWidth*.6,resize.width+event.clientX-resize.x));}
</script>
<template>
 <section :class="['marking-library',{drawer,closed:drawer&&!opened}]" :style="drawer?{width:opened?width+'px':'46px'}:undefined" aria-label="花纹库" tabindex="0" @keydown="libraryKey">
  <div class="library-heading"><strong v-if="opened||!drawer">{{zh?'花纹库':localize('Marking library')}} · {{regions.length}}</strong><button v-if="drawer" :aria-expanded="opened" @click="opened=!opened">{{opened?'‹':'›'}}</button></div>
  <div v-if="pendingSelection!==null" class="draft-switch-confirm" role="status"><p>{{zh?'当前源花纹有未保存草稿。':localize('This source has an unsaved draft.')}}</p><button :disabled="store.busy" @click="discardSwitch">{{zh?'取消草稿并切换':localize('Discard draft and switch')}}</button><button @click="pendingSelection=null">{{zh?'继续编辑当前花纹':localize('Keep editing')}}</button></div><template v-if="opened||!drawer">
   <input v-model="search" :placeholder="zh?'搜索名称、类别或颜色':localize('Search names, groups or colors')" aria-label="搜索花纹">
   <div class="library-batch"><button :disabled="store.busy||!regions.length" @click="checked=regions.map(r=>r.piece.id)">{{zh?'全选花纹':localize('Select all')}}</button><button :disabled="!checked.length" @click="checked=[]">{{zh?'取消全选':localize('Clear selection')}}</button><button :disabled="store.busy||editorDirty||!checked.length" @click="pendingDelete=[...checked]">{{zh?'删除所选':localize('Delete selected')}} · {{checked.length}}</button></div>
   <div v-if="pendingDelete.length" role="alertdialog" :aria-label="zh?'确认删除花纹':localize('Confirm deletion')" class="delete-confirm"><p>{{zh?'删除所选花纹及其关联贴附？可通过撤销恢复；锁定花纹会阻止整批删除。':localize('Delete sources and their placements? Undo restores them; locked sources prevent the entire operation.')}} {{pendingDelete.length}}</p><button :disabled="store.busy||editorDirty" @click="deleteIds(pendingDelete)">{{zh?'确认删除':localize('Confirm delete')}}</button><button @click="pendingDelete=[]">{{zh?'取消':localize('Cancel')}}</button></div>
   <label class="library-zoom">{{zh?'预览缩放':localize('Preview scale')}}<input v-model.number="zoom" type="range" min=".6" max="2" step=".1"><span>{{Math.round(zoom*100)}}%</span></label>
   <p v-if="drawer" class="drag-help">{{zh?'将花纹拖到可见模型表面，松开即按毫米尺寸贴附。中键旋转检查，每次拖放生成独立副本。':localize('Drop onto the visible model to attach at its millimetre size. Middle-drag to inspect; each drop creates an independent copy.')}}</p><LegacyProjection v-if="drawer" :language="language"/>
   <div ref="libraryContent" class="library-content" :style="region?{gridTemplateRows:`minmax(50px,${1-detailShare}fr) 8px minmax(100px,${detailShare}fr)`}:undefined"><div class="library-groups"><section v-for="group in groups" :key="group.key"><h3>{{group.key.replace('front',zh?'正面':localize('Front')).replace('back',zh?'背面':localize('Back'))}}</h3><div class="region-grid" :style="{'--region-size':100*zoom+'px','--preview-height':85*zoom+'px'}"><div v-for="r in group.items" :key="r.piece.id" class="region-tile"><button :data-region-id="r.piece.id" :draggable="drawer&&!store.busy&&!editorDirty" @dragstart="dragSource($event,r.piece.id)" @dragend="endSourceDrag" :class="['region-card',{active:selected===r.piece.id}]" @click="cardClick($event,r.piece.id)"><svg :viewBox="box(r.piece)"><path :d="piecePath(r.piece)" :fill="r.piece.color" fill-rule="evenodd" stroke="var(--text-muted)" vector-effect="non-scaling-stroke" stroke-width="1.25" stroke-linejoin="round"/></svg><small>{{r.piece.name}}</small></button><input class="region-check" type="checkbox" :checked="checked.includes(r.piece.id)" :aria-label="(zh?'选择花纹 ':localize('Select marking '))+r.piece.name" @change="toggleChecked(r.piece.id)"><button class="region-delete" :disabled="store.busy||editorDirty" :aria-label="(zh?'删除花纹 ':localize('Delete marking '))+r.piece.name" @click="deleteIds([r.piece.id])">×</button></div></div></section><p v-if="regions.length&&!filtered.length" role="status">{{zh?'没有匹配的花纹，请修改搜索内容。':localize('No matching markings. Try a different search.')}}</p><p v-if="!regions.length">{{zh?'在花纹页面上传正背双视图，自动拆分后会显示在这里。':localize('Upload front and back views on the Markings page to populate this library.')}}</p></div>
   <div v-if="region" class="detail-resizer" role="separator" tabindex="0" aria-orientation="horizontal" :aria-valuenow="Math.round(detailShare*100)" :aria-label="zh?'调整花纹详情高度':localize('Resize marking details')" @pointerdown="detailDrag=true;($event.currentTarget as HTMLElement).setPointerCapture($event.pointerId);$event.preventDefault()" @pointermove="resizeDetail" @pointerup="endDetail" @pointercancel="endDetail" @lostpointercapture="endDetail" @keydown.up.prevent="detailShare=Math.min(.9,detailShare+.05);endDetail()" @keydown.down.prevent="detailShare=Math.max(.2,detailShare-.05);endDetail()" @dblclick="detailShare=.68;endDetail()"><span/></div><section v-if="region" class="region-settings"><SourceRegionEditor :key="region.piece.id" :piece="region.piece" :reference="store.data.project?.references?.find(r=>r.id===region?.referenceId)" :language="language" :busy="store.busy" :reset-token="sourceReset" :save-error="sourceSaveError" @dirty="editorDirty=$event;if(!$event)sourceSaveError=''" @commit="saveSource"/>
    <p v-if="attachNotice" class="attach-notice" role="status">{{attachNotice}}</p><fieldset class="source-metadata" :disabled="store.busy||editorDirty">
    <label>{{zh?'名称':localize('Name')}}<input :value="region.piece.name" maxlength="120" @change="metadata('name',($event.target as HTMLInputElement).value)"></label>
    <div class="two-col"><label>{{zh?'部位分类':localize('Body part')}}<select :value="region.anatomy?.part??'unknown'" aria-label="花纹部位分类" @change="classify(($event.target as HTMLSelectElement).value as BodyPart,region.anatomy?.side??'unknown')"><option v-for="part in bodyParts" :key="part" :value="part">{{partName(part,zh)}}</option></select></label><label>{{zh?'角色左右侧':localize('Character side')}}<select :value="region.anatomy?.side??'unknown'" aria-label="花纹左右侧" @change="classify(region.anatomy?.part??'unknown',($event.target as HTMLSelectElement).value as BodySide)"><option v-for="side in (['center','left','right','unknown'] as const)" :key="side" :value="side">{{sideName(side,zh)}}</option></select></label></div><small v-if="region.anatomy?.method==='silhouette-1'">{{zh?'部位是位置建议，不是语义识别。角与耳朵边界不明确的区域保留为待分类；请核对原图后选择角或耳朵及左右侧。':localize('Position hint only. Ambiguous horn/ear regions remain unclassified; inspect the artwork and set the part and side.')}}</small><div class="two-col"><label>{{zh?'分类':localize('Category')}}<input :value="region.category" maxlength="80" @change="metadata('category',($event.target as HTMLInputElement).value)"></label><label>{{zh?'颜色':localize('Color')}}<input type="color" :value="region.piece.color" @change="metadata('color',($event.target as HTMLInputElement).value)"></label></div>
    </fieldset>
    <template v-if="drawer"><button class="primary" :disabled="store.busy||editorDirty||!store.data.project?.surface||!placementAnatomies(region).some(a=>a.part!=='unknown')" @click="autoAttach">{{zh?'自动匹配此花纹的模型部位':localize('Automatically match this source')}}</button><div class="two-col"><label>X mm<input v-model.number="offsetX" type="number"></label><label>Y mm<input v-model.number="offsetY" type="number"></label></div><label class="check-label"><input v-model="replaceManual" type="checkbox">{{zh?'允许替换已有人工编辑':localize('Replace existing manual edits')}}</label><button class="primary" :disabled="store.busy||editorDirty||!store.data.project?.surface" @click="attach">{{zh?'贴附到当前模型':localize('Attach to current model')}}</button><small>{{zh?'使用花纹所属正 / 背视图投影。可在展开前贴附，偏移以毫米计算。':localize('Projects from the source front/back view, including before unwrapping. Offsets are in mm.')}}</small></template>
    <button class="danger" :disabled="store.busy||editorDirty" @click="remove">{{zh?'删除此花纹':localize('Delete marking source')}}</button>
   </section></div>
  </template>
  <div v-if="drawer&&opened" class="drawer-resizer" role="separator" aria-label="调整花纹抽屉宽度" @pointerdown="start" @pointermove="drag" @pointerup="resize=undefined;endDetail()" @pointercancel="resize=undefined"></div>
 </section>
</template>
<style scoped>
.marking-library{display:flex;flex-direction:column;min-height:0;background:var(--panel);border-left:1px solid var(--border);padding:14px;gap:10px;overflow:hidden}.library-heading{display:flex;justify-content:space-between;align-items:center}.library-heading strong{font-size:14px}.library-zoom{display:flex;align-items:center;gap:8px;font-size:11px}.library-zoom input{width:80px;flex:1}.library-groups{overflow:auto;min-height:80px;flex:1}.library-groups h3{font-size:11px;color:var(--accent)}.region-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,var(--region-size)),1fr));gap:8px}.region-card{padding:5px;background:var(--panel);min-width:0;text-align:left}.region-card svg{height:var(--preview-height,85px);width:100%;background:var(--canvas);border-radius:3px}.region-card small{display:block;font-size:10px;overflow-wrap:anywhere;margin-top:4px}.region-card.active{border-color:var(--accent)}.source-region-preview{height:230px;background:var(--canvas)}.region-settings{max-height:55%;overflow:auto;display:grid;gap:10px;padding-top:12px;border-top:1px solid var(--border)}.region-settings label{font-size:11px}.region-settings details>*{margin-block:8px}.region-settings small,.library-groups p{font-size:11px;color:var(--accent)}.drawer{position:relative;flex-shrink:0;border-left:0;border-right:1px solid var(--border)}.drawer.closed{padding:8px}.drawer-resizer{position:absolute;right:0;top:0;bottom:0;width:5px;cursor:col-resize;touch-action:none}.drawer-resizer:hover{background:var(--accent-soft)}
</style>


<style scoped>.library-batch{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.region-tile{position:relative;min-width:0}.region-tile .region-card{width:100%;height:100%}.region-check{position:absolute;top:6px;left:6px;width:16px!important;height:16px;margin:0;background:white}.region-delete{position:absolute;top:3px;right:3px;padding:1px 6px;background:var(--panel);font-size:17px;line-height:22px}.delete-confirm{padding:12px;border:1px solid var(--border);background:var(--panel-soft)}.delete-confirm p{line-height:1.6}</style>

<style scoped>.source-metadata{display:grid;gap:10px;border:0;padding:0;margin:0;min-width:0}.draft-switch-confirm{padding:8px;border:1px solid var(--accent);font-size:11px}.draft-switch-confirm p{margin:0 0 6px}.draft-switch-confirm button{font-size:11px;padding:5px}.region-settings{max-height:70%}</style>

<style scoped>.library-content{display:grid;flex:1;min-height:0;overflow:hidden}.library-content .region-settings{max-height:none;min-height:0;display:block;padding-top:8px}.region-settings>*{margin-bottom:10px}.detail-resizer{cursor:row-resize;touch-action:none;display:flex;align-items:center;justify-content:center;background:var(--panel-blue)}.detail-resizer span{height:3px;width:48px;background:var(--accent)}.detail-resizer:hover,.detail-resizer:focus-visible{background:var(--studio-sky)}.marking-library{height:100%;box-sizing:border-box}</style>
